// Vicero signs every call: hex HMAC-SHA256 over "<timestamp>." + the raw body, using
// N8N_WEBHOOK_SIGNING_SECRET (apps/api/app/integrations/n8n_client.py sign()/verify_callback()).
// Fails CLOSED: no secret configured, missing headers, stale timestamp or bad MAC => rejected.
const crypto = require('crypto');
const item = $input.first();
const reject = (reason) => [{ json: { verified: false, reason } }];
const secret = $env['N8N_WEBHOOK_SIGNING_SECRET'] || '';
if (!secret) return reject('signing secret is not configured on this n8n');
const h = item.json.headers || {};
const sig = String(h['x-vicero-signature'] || '');
const ts = String(h['x-vicero-timestamp'] || '');
if (!sig || !ts) return reject('missing signature headers');
if (!/^\d{1,12}$/.test(ts) || Math.abs(Date.now() / 1000 - Number(ts)) > 300) return reject('stale or malformed timestamp');
if (!item.binary || !item.binary.data) return reject('raw body unavailable (Webhook option rawBody must be on)');
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');
const a = Buffer.from(expected, 'utf8');
const b = Buffer.from(sig, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject('bad signature');
return [{ json: { ...item.json, verified: true } }];

// DEMO FIXTURE - every name, id, price, doctor, slot and order in this workflow is fictional demo data.
// State (bookings, counters) lives in n8n workflow static data and is NOT part of this export.
const body = $input.first().json.body || {};
const a = body.args || {};
const S = $getWorkflowStaticData('global');
S.bookings = S.bookings || {};
S.counter = S.counter || 0;
const need = (fields) => fields.filter((f) => a[f] === undefined || a[f] === null || String(a[f]).trim() === '');
const bad = (error, extra = {}) => [{ json: { ok: false, error, ...extra } }];
const nextId = (prefix) => { S.counter += 1; return prefix + '-' + String(1000 + S.counter); };
const isDate = (s) => /^\d{4}-\d{2}-\d{2}$/.test(String(s));
const isTime = (s) => /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s));

const DOCTORS = { general: ['Dr. Meera Iyer'], dental: ['Dr. Arjun Rao'], pediatrics: ['Dr. Nisha Kapoor'], dermatology: ['Dr. Sameer Bhatt'] };
const HOURS = ['09:00', '10:00', '11:00', '12:00', '14:00', '15:00', '16:00'];
const taken = (spec, date, time) => Object.values(S.bookings).some((b) => b.status === 'confirmed' && b.specialty === spec && b.date === date && b.time === time);
const free = (spec, date) => HOURS.filter((t) => !taken(spec, date, t));
switch (a.action) {
  case 'get_slots': {
    const m = need(['specialty', 'date']); if (m.length) return bad('missing fields: ' + m.join(', '));
    if (!DOCTORS[a.specialty]) return bad('unknown specialty', { specialties: Object.keys(DOCTORS) });
    if (!isDate(a.date)) return bad('date must be YYYY-MM-DD');
    return [{ json: { ok: true, specialty: a.specialty, doctor: DOCTORS[a.specialty][0], date: a.date, open_slots: free(a.specialty, a.date) } }];
  }
  case 'book_appointment': {
    const m = need(['patient_name', 'phone', 'specialty', 'date', 'time']); if (m.length) return bad('missing fields: ' + m.join(', '));
    if (!DOCTORS[a.specialty]) return bad('unknown specialty', { specialties: Object.keys(DOCTORS) });
    if (!isDate(a.date) || !isTime(a.time)) return bad('date must be YYYY-MM-DD and time HH:MM (24h)');
    if (!HOURS.includes(a.time)) return bad('not a bookable slot', { open_slots: free(a.specialty, a.date) });
    if (taken(a.specialty, a.date, a.time)) return bad('slot already taken', { open_slots: free(a.specialty, a.date) });
    const id = nextId('CCA');
    S.bookings[id] = { id, patient_name: a.patient_name, phone: a.phone, specialty: a.specialty, doctor: DOCTORS[a.specialty][0], date: a.date, time: a.time, reason: a.reason || null, status: 'confirmed' };
    return [{ json: { ok: true, appointment_id: id, doctor: DOCTORS[a.specialty][0], specialty: a.specialty, date: a.date, time: a.time, status: 'confirmed', message: 'Please arrive 10 minutes early and bring any previous reports.' } }];
  }
  case 'cancel_appointment': {
    const b = S.bookings[a.appointment_id]; if (!b) return bad('no appointment found for that id');
    b.status = 'cancelled';
    return [{ json: { ok: true, appointment_id: b.id, status: 'cancelled' } }];
  }
  default: return bad('unknown action', { valid_actions: ['get_slots', 'book_appointment', 'cancel_appointment'] });
}
